00050 struct AVCNalType {
00051     enum Enum {
00052         Unspecified = 0,
00053         CodedSlice_NonIDR = 1,
00054         CodedSlice_A = 2,
00055         CodedSlice_B = 3,
00056         CodedSlice_C = 4,
00057         CodedSlice_IDR = 5,
00058         SEI = 6,
00059         SPS = 7,
00060         PPS = 8,
00061         AUD = 9,
00062         EndOfSequence = 10,
00063         EndOfStream = 11,
00064         FillerData = 12,
00065         SPSExt = 13,
00066         Prefix = 14,
00067         SubsetSPS = 15,
00068         DPS = 16,
00069         // Reserved (17-18)
00070         CodedSlice_Aux = 19,
00071         CodedSlice_Ext = 20,
00072         CodedSlice_DepthExt = 21
00073         // Reserved (22-23)
00074         // Unspecified (24-31)
00075     };
00076 };
